rows=[];decisions=[];papers=[]
def paper(country,year,section,source,solution,date,complete=True):
 global ctx
 ctx=dict(country=country,competition='Lithuanian Mathematical Olympiad' if country=='Lithuania' else 'Latvian Mathematical Olympiad',year=year,section=section,sourceUrl=source,solutionUrl=solution,sittingDate=date)
 papers.append(ctx|{'complete':complete})
def add(num,rating,topic,statement,reason,tags,solution=None,notes='',appearances=None):
 p=ctx|dict(id=f"baltic-{ctx['country'].lower()}-{ctx['year']}-{ctx['section'].replace(' ','-')}-{num}",number=num,difficulty=rating,topic=topic,statement=statement,ratingReason=reason,tags=tags,reviewStatus='individually-assessed',solutionKind='original-exposition' if solution else 'source-link',solutionCredit='Independent mathematical exposition for Olympiad Atlas' if solution else 'Official competition solutions',solution=solution or ('The organiser’s worked solution is linked below, in '+('Lithuanian.' if ctx['country']=='Lithuania' else 'Latvian.')),notes='English mathematical paraphrase of the official national paper. '+notes)
 if appearances:p['appearances']=[ctx|a for a in appearances]
 rows.append(p)
 decisions.append({k:p[k] for k in ['id','country','competition','year','section','number','difficulty','ratingReason']}|{'included':True})
def ex(num,rating,reason):
 decisions.append({k:ctx[k] for k in ['country','competition','year','section']}|dict(number=num,difficulty=rating,included=False,reason=reason))
def dup(num,rating,section,othernum):
 decisions.append({k:ctx[k] for k in ['country','competition','year','section']}|dict(number=num,difficulty=rating,included=rating>=4 and rating<=7,duplicateOf={'section':section,'number':othernum},reason='Identical task appearing in the other age group; counted once in the bank.'))
